import { z } from 'zod';

import { api } from '@/lib/api-client';
import { useNotifications } from '@/components/ui/notifications';
import { QueryConfig } from '@/lib/react-query';
import { User } from '@/types/api';

export const updateRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateRoleInput = z.infer<typeof updateRoleInputSchema>;

export const updateUserRole = ({
  userId,
  data,
}: {
  userId: string;
  data: UpdateRoleInput;
}) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const { addNotification } = useNotifications();
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (res, vars, ctx) => {
      // Update local cache optimistically to ensure the new role appears immediately
      queryClient.setQueryData<User[]>(['users'], (oldData) => {
        if (!oldData) return oldData;
        return oldData.map((u) => (u.id === vars.userId ? { ...u, role: vars.data.role } : u));
      });

