import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { User } from '@/types/api';

import { useUsers } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

const UserRoleField = ({ user }: { user: User }) => {
  const { mutate, isPending } = useUpdateUserRole();

  return (
    <select
      className="rounded border border-gray-300 px-2 py-1 text-sm dark:border-gray-600 dark:bg-gray-800 dark:text-white"
      value={user.role}
      onChange={(e) =>
